const itemJson = ($input.item && $input.item.json) ? $input.item.json : {};
const html = itemJson.body || "";
let defaultChannel = "Telegram";
try {
  defaultChannel = $node["Channel List"].json.channel || "Telegram";
} catch (e) {}
const results = [];
if (!html) return results;

async function translateToEnglish(text) {
  if (!text || text.trim().length === 0) return text;
  try {
    const chunk = text.substring(0, 1500);
    const url = "https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=en&dt=t&q=" + encodeURIComponent(chunk);
    const res = await fetch(url);
    const data = await res.json();
    if (data && data[0]) {
      return data[0].map(item => item[0]).join("");
    }
  } catch (err) {}
  return text;
}

const wraps = html.split('<div class="tgme_widget_message_wrap');
for (let i = 1; i < wraps.length; i++) {
  const wrap = wraps[i];
  const postMatch = /data-post="([^"]+)"/.exec(wrap);
  if (!postMatch) continue;
  const postPath = postMatch[1];

  const textMatch = /<div class="tgme_widget_message_text[^"]*"[^>]*>([\s\S]*?)<\/div>/.exec(wrap);
  const rawText = textMatch ? textMatch[1] : "";
  const cleanText = rawText.replace(/<[^>]+>/g, '').trim();
  if (!cleanText) continue;

  const timeMatch = /<time[^>]*datetime="([^"]+)"/.exec(wrap);
  const isoDate = timeMatch ? timeMatch[1] : new Date().toISOString();

  const channelUsername = postPath ? postPath.split('/')[0] : defaultChannel;
  const translatedText = await translateToEnglish(cleanText);
  const lines = translatedText.split('\n').map(l => l.trim()).filter(Boolean);
  const title = lines[0] ? lines[0].substring(0, 200) : "Telegram Incident Report";

  results.push({
    json: {
      title: `[@${channelUsername}] ${title}`,
      description: translatedText,
      source_name: `Telegram (@${channelUsername})`,
      source_url: `https://t.me/${postPath}`,
      is_darknet: false,
      date_reported: isoDate
    }
  });
}

return results.slice(-5);
